	b := s.keyFor(mk("REDACTED"))
	c := s.keyFor(mk("REDACTED"))
	if a == b || a == c {
		t.Error("URLs with different userinfo must give different keys")
	}
	if a != s.keyFor(mk("REDACTED")) {
		t.Error("trailing slash must still be ignored")
	}
}
